import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"🔬 科学快报 | 2026年7月27日（事后重建版 · 第 ? 期）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-27.md","filePath":"science-log/src/reconstructed/2026-07-27.md"}'),n={name:"science-log/src/reconstructed/2026-07-27.md"};function s(i,e,l,g,h,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年7月27日-事后重建版-·-第-期" tabindex="-1">🔬 科学快报 | 2026年7月27日（事后重建版 · 第 ? 期） <a class="header-anchor" href="#🔬-科学快报-2026年7月27日-事后重建版-·-第-期" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月27日（事后重建版 · 第 ? 期）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日（周一）CrossRef 上 Nature 命中 9 条（其中研究论文 2 条，其余为新闻/Briefing 已剔除）、PNAS 命中 38 条、Science 前缀 10.1126 当日仅命中 8 条且全为新闻类 dataset 条目、无研究论文，故科学 5 篇由 <strong>Nature 2 + PNAS 3</strong> 组成。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607270000 TO 202607272359]</code>（cs.AI，命中 30 条）｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="⚡-相位均匀的混合卤化物钙钛矿-让叠层光伏站得更稳" tabindex="-1">⚡ 相位均匀的混合卤化物钙钛矿，让叠层光伏站得更稳 <a class="header-anchor" href="#⚡-相位均匀的混合卤化物钙钛矿-让叠层光伏站得更稳" aria-label="Permalink to &quot;⚡ 相位均匀的混合卤化物钙钛矿，让叠层光伏站得更稳&quot;">​</a></h3><p><strong>Phase-homogeneous mixed-halide perovskites for stable tandem photovoltaics</strong><em>Nature（2026-07-27 在线）</em></p><p>宽带隙混合卤化物钙钛矿是叠层电池的关键顶层材料，但它在成膜阶段就会发生相分离——富碘相与富溴相的成核速率不对称，PbBrₓ 比 PbIₓ 先析出，于是膜内从一开始就不均匀。过去靠调节 Pb²⁺ 配位强度来均一化，问题是这种调节对所有 Pb²⁺ 中心一视同仁，无法专门约束「跑得快的那个」。作者（Pengju Shi、Jiale Zhuang 等，29 人合作）改从路易斯碱的<strong>软硬度</strong>下手：用分子偶极去约束氧供体最外层电子的极化率，让更「硬」的氧供体优先配位更「硬」的 PbBrₓ，选择性拖慢富溴相成核，使其与 PbIₓ 同步。结果得到成分均匀的宽带隙膜，在 1.62 eV、1.68 eV、1.88 eV 三个带隙上都实现了效率与稳定性同时提升，1 sun、65 °C 下 T90 维持 1,500 小时；与红外吸收层组成的钙钛矿—有机叠层器件也受益。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10929-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10929-2</a></p><h3 id="🧪-把维生素-b6-的辅酶变成光酶-plp-进入「暗空间」" tabindex="-1">🧪 把维生素 B6 的辅酶变成光酶：PLP 进入「暗空间」 <a class="header-anchor" href="#🧪-把维生素-b6-的辅酶变成光酶-plp-进入「暗空间」" aria-label="Permalink to &quot;🧪 把维生素 B6 的辅酶变成光酶：PLP 进入「暗空间」&quot;">​</a></h3><p><strong>Pyridoxal photoenzymes for asymmetric radical–radical cross-couplings</strong><em>Nature（2026-07-27 在线）</em></p><p>人工光酶长期依赖黄素、烟酰胺这类可见光强吸收、激发态寿命够长的辅因子；而磷酸吡哆醛（PLP）虽在天然酶里催化转氨、脱羧等上百种反应，却因光物理性质差，一直落在「光酶暗空间」里。作者（Cole C. Sorensen、Suhao Wang 等）抓住 PLP 的醌式中间体：它的激发态是强单电子还原剂，只是难以直接激发。解法是双管齐下——改用非天然苄胺底物，并借外加光敏剂的 Förster 共振能量转移（FRET）去「点亮」醌式激发态。由此把 PLP 酶改造为可做不对称自由基—自由基交叉偶联的光催化剂，等于给一个拥有巨大多样性的天然酶家族装上了光化学的新反应通道。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10930-9" target="_blank" rel="noreferrer">10.1038/s41586-026-10930-9</a></p><h3 id="🧠-甲硫氨酸氧化如何拆掉-tdp-43-的「装配线」" tabindex="-1">🧠 甲硫氨酸氧化如何拆掉 TDP-43 的「装配线」 <a class="header-anchor" href="#🧠-甲硫氨酸氧化如何拆掉-tdp-43-的「装配线」" aria-label="Permalink to &quot;🧠 甲硫氨酸氧化如何拆掉 TDP-43 的「装配线」&quot;">​</a></h3><p><strong>Methionine oxidation alters both helical assembly and disordered contacts in human TDP-43 C-terminal domain phase separation</strong><em>PNAS（2026-07-27）</em></p><p>TDP-43 的 C 端结构域（CTD）靠一段保守区（CR）的螺旋—螺旋相互作用自组装，两侧的无序区（IDR）则以芳香与疏水残基的瞬时接触参与相分离；CTD 上 10 个甲硫氨酸恰好在这两类区域各占一半，因此对氧化修饰格外敏感。此前已知甲硫氨酸氧化会损害 TDP-43 相分离，但说不清是「拆螺旋」还是「断接触」。作者（Busra Ozguney、Ryan Z. Puterbaugh、Jeetain Mittal 等）用 NMR 结合分子动力学模拟，把两条路径分开量化：氧化同时削弱 CR 的螺旋装配与 IDR 的 disordered 接触。这为 ALS/FTD 中「氧化应激 → TDP-43 病理聚积」补上了分子层面的因果环节。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2537431123" target="_blank" rel="noreferrer">10.1073/pnas.2537431123</a></p><h3 id="🐋-须鲸的「冲刺式」心跳-憋气状态下做高强度无氧运动" tabindex="-1">🐋 须鲸的「冲刺式」心跳：憋气状态下做高强度无氧运动 <a class="header-anchor" href="#🐋-须鲸的「冲刺式」心跳-憋气状态下做高强度无氧运动" aria-label="Permalink to &quot;🐋 须鲸的「冲刺式」心跳：憋气状态下做高强度无氧运动&quot;">​</a></h3><p><strong>Sprint-like cardiac dynamics support repeated acrobatic lunges in foraging rorqual whales</strong><em>PNAS（2026-07-27）</em></p><p>潜水动物的典型模式是潜水反射压低心率以省氧，运动时心率随活动上升、随后回落。但滤食性须鲸是个极端例外：一次潜水里大部分时间在滑翔与滤水，真正耗能的是短促而猛烈的冲刺式吞食（lunge）。作者（Ashley M. Blawas、David E. Cade、Ari S. Friedlaender 等 9 人）用生物记录标签发现，心率随每次 lunge 反复升高，而在滤水阶段只缓慢下降——与其它潜水动物「心率—活动」强耦合的模式明显不同。作者据此推断，短促高功率的 lunge 主要依赖糖酵解底物而非有氧底物；滤水阶段的高心率则可能用于处理后摄食期的生理负担。这把「潜水反射」从一个静态开关，改写成一个按行为阶段重构的调度问题。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2613082123" target="_blank" rel="noreferrer">10.1073/pnas.2613082123</a></p><h3 id="❄️-湖泊冰盖的「临界气温」-越过阈值-敏感性暴涨-22-倍" tabindex="-1">❄️ 湖泊冰盖的「临界气温」：越过阈值，敏感性暴涨 22 倍 <a class="header-anchor" href="#❄️-湖泊冰盖的「临界气温」-越过阈值-敏感性暴涨-22-倍" aria-label="Permalink to &quot;❄️ 湖泊冰盖的「临界气温」：越过阈值，敏感性暴涨 22 倍&quot;">​</a></h3><p><strong>Rapid acceleration of ice-cover loss from Northern Hemisphere lakes above critical air temperature thresholds</strong><em>PNAS（2026-07-27）</em></p><p>湖泊冰盖退缩是气候变暖的标志性现象，但冰盖对热强迫的<strong>敏感性</strong>如何随气候带变化，一直缺少大范围定量。作者（Jian Zhou、Weijia Wang、Linwang Yuan 等）分析了 2000—2022 年北半球 724 个湖泊的冰物候数据，发现明显的不对称：封冻—解冻周期中，「冰盖消融」过程对增温的响应显著强于「冰盖形成」过程。更关键的是识别出冬季平均气温的临界阈值区间 −13.7 °C 至 −6.8 °C，越过该区间后物候敏感性呈非线性加速，冰量损失的敏感度最高可增大 22 倍——这是典型的阈值型崩塌信号，意味着同样的增温幅度，在临界带附近的湖泊会损失远多于高纬湖泊的冰期。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2610752123" target="_blank" rel="noreferrer">10.1073/pnas.2610752123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🪞-智能体把「停滞」误读成「进展」-progress-mirage" tabindex="-1">🪞 智能体把「停滞」误读成「进展」：progress mirage <a class="header-anchor" href="#🪞-智能体把「停滞」误读成「进展」-progress-mirage" aria-label="Permalink to &quot;🪞 智能体把「停滞」误读成「进展」：progress mirage&quot;">​</a></h3><p><strong>When Do Agent Loops Mistake Stagnation for Progress? Self-Evaluation Bias and Externally Grounded Verification in Long-Running Autonomous LLM Agent Loops</strong><em>arXiv（2026-07-27）</em></p><p>长程自主 agent 的完成判定往往由它自己给出，于是「自我评估偏差」生效：看似合理的改动被当成进展，真实世界状态却停滞甚至倒退。作者（Hyundoo Park、Byungho Choi）把这种失效命名为 <strong>progress mirage</strong>，并造了一个受控试验台——固定 agent 与工具面，只改变「把关评估器所依托的信息通道类型」。54 个循环里，前沿模型每次都声称有改进，但实测变化量 ≤0 的占 56%；自我判定闸门退化为「全盘接受」，反而把它曾达到的最好部署状态侵蚀了 19%。即便给最强的「带内」裁判（读完整产物、diff 与自身历史判决）仍有 44% 的循环被误接受——说明验证必须锚定在不可伪造的外部世界状态上，而不是更聪明的文本审阅。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.25152" target="_blank" rel="noreferrer">2607.25152</a></p><h3 id="😱-情绪在-llm-群体中传染-涌现式情绪感染" tabindex="-1">😱 情绪在 LLM 群体中传染：涌现式情绪感染 <a class="header-anchor" href="#😱-情绪在-llm-群体中传染-涌现式情绪感染" aria-label="Permalink to &quot;😱 情绪在 LLM 群体中传染：涌现式情绪感染&quot;">​</a></h3><p><strong>How Affect Propagates among LLM Agents: Emergent Emotional Contagion in Crowd Simulation</strong><em>arXiv（2026-07-27）</em></p><p>作者（Funda Durupinar）在人群仿真里给每个 agent 视觉、听觉、触觉三类感知通道，由 LLM 结合被提示的人格档案（Big Five）、记忆、当前情绪状态与情境上下文做 appraisal（评价），再更新内部情绪并选择外显表达。架构里<strong>没有任何</strong>手写的「情绪直接传递」机制，个体间影响完全经由「感知—评价—表达」闭环涌现；情绪表示则用 Russell 环状模型。为了控制延迟，低层转向与导航交给传统人群仿真器，与 LLM 认知层解耦。这提供了一个干净的实验范式：把社会性情绪现象拆成「感知带宽 + 评价函数」两个可调旋钮，从而检验哪些集体情绪动力学是 LLM 语义先验带来的、哪些是架构涌现的。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.25140" target="_blank" rel="noreferrer">2607.25140</a></p><h3 id="🪆-matryoshka-agent-把子智能体套起来做长程-mle" tabindex="-1">🪆 Matryoshka Agent：把子智能体套起来做长程 MLE <a class="header-anchor" href="#🪆-matryoshka-agent-把子智能体套起来做长程-mle" aria-label="Permalink to &quot;🪆 Matryoshka Agent：把子智能体套起来做长程 MLE&quot;">​</a></h3><p><strong>Matryoshka Agent: Unfolding Sub-Agents for Long-Horizon Machine Learning Engineering</strong><em>arXiv（2026-07-27）</em></p><p>机器学习工程任务要在昂贵、反馈驱动的环境交互中反复调试与精化，是典型的长程决策问题；单体 agent 必须同时扛住超长且嘈杂的上下文、探索巨大解空间，还受限于模型容量与算力预算。作者（Rushi Qiang、Changhao Li、Haotian Sun、Yuchen Zhuang、Chao Zhang）提出分层框架：高层 Orchestrator 只维护紧凑的长程探索状态并下达战略指令，低层 Sub-Agent 通过标准化 Tool 接口直接与环境交互、执行具体解法尝试。这种「战略探索 / 昂贵执行」解耦大幅削减了长上下文推理负担，使分层嵌套（套娃式）成为长程工程任务的通用脚手架。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.25090" target="_blank" rel="noreferrer">2607.25090</a></p><h3 id="🖥️-智能体需要自己的「操作系统」-从-posix-与-kubernetes-借方法" tabindex="-1">🖥️ 智能体需要自己的「操作系统」：从 POSIX 与 Kubernetes 借方法 <a class="header-anchor" href="#🖥️-智能体需要自己的「操作系统」-从-posix-与-kubernetes-借方法" aria-label="Permalink to &quot;🖥️ 智能体需要自己的「操作系统」：从 POSIX 与 Kubernetes 借方法&quot;">​</a></h3><p><strong>Towards an Agent Operating System - Lessons from Classical and Cloud OS</strong><em>arXiv（2026-07-27）</em></p><p>作者（Gosia Steinder、Hubertus Franke）把平台软件的演化归纳成同一条弧线：先是框架林立、实现各异的实验期，随后沉淀出少量语义明确的稳定抽象，最后围绕抽象整合成可移植的平台——POSIX 之于经典 OS，Kubernetes 之于云。agentic AI 正处于第三波浪潮的实验期：框架与协议已有几十个，但对「核心抽象是什么、它们提供什么保证」没有共识，于是应用无法可移植地编写、平台无法可靠组合、行业停在原型阶段。文章主张沿用前两波的方法论：把经典 OS 与云 OS 的原语扩展到随机、自然语言驱动的智能体上，由此导出新的抽象。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.25076" target="_blank" rel="noreferrer">2607.25076</a></p><h3 id="🔌-用强化学习给-gpu-限功-从单卡到整机队的实测功率控制" tabindex="-1">🔌 用强化学习给 GPU 限功：从单卡到整机队的实测功率控制 <a class="header-anchor" href="#🔌-用强化学习给-gpu-限功-从单卡到整机队的实测功率控制" aria-label="Permalink to &quot;🔌 用强化学习给 GPU 限功：从单卡到整机队的实测功率控制&quot;">​</a></h3><p><strong>Cutting AI Datacenter Energy with Reinforcement Learning: Measured Power Control of LLM Training from One GPU to the Fleet</strong><em>arXiv（2026-07-27）</em></p><p>RL 后训练已是现代语言模型开发的主流，但其在 GPU 上的功率行为此前没被刻画过，而数据中心仍用静态封顶与被动降频这类「对负载无感」的机制管功率。作者（Eliseo Curcio）在 7B/14B/72B 三个规模、1—4 张 A100 上给 GRPO 训练做半秒级功率遥测（38 万+ 采样），并训练 PPO 元控制器按实测功率调节工作负载自身的生成参数。在 7B 的 500 步完整轨迹上，功率限额违规下降 89.8%、token 产出提升 18.1%、能效（tokens per MWh）提升 26.2%；但同一控制器直接上 72B 时出现可复现的零效应，诊断为模型分片导致「组大小」执行器失去权限。作者用执行器权限扫描定位出「占用 vs 体量」原则：换用生成并发度作执行器仍保有 17—22% 的功率权限，据此重建的控制器能真正控制 72B 的在线 rollout。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.11226" target="_blank" rel="noreferrer">2608.11226</a></p><blockquote><p>📅 日期：2026-07-27 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const c=a(n,[["render",s]]);export{u as __pageData,c as default};
